package com.example.jobfinderapp.activities;
import android.os.Bundle;import android.widget.TextView;import androidx.appcompat.app.AppCompatActivity;import com.example.jobfinderapp.R;import com.example.jobfinderapp.database.DBHelper;import java.util.Map;
public class ApplicantDetailActivity extends AppCompatActivity{public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_applicant_detail);int id=getIntent().getIntExtra("APPLICATION_ID",-1),company=getIntent().getIntExtra("COMPANY_ID",-1);Map<String,Object> m=DBHelper.getInstance(this).getApplicationDetail(id,company);if(m==null){finish();return;}((TextView)findViewById(R.id.tvApplicantDetail)).setText(String.valueOf(m.get("fullname"))+"\n"+String.valueOf(m.get("email"))+"\n"+String.valueOf(m.get("phone"))+"\n\nVị trí: "+String.valueOf(m.get("job_title"))+"\nTrạng thái: "+String.valueOf(m.get("status"))+"\n\nLời nhắn: "+String.valueOf(m.get("message"))+"\n\nCV: "+String.valueOf(m.get("cv_name"))+"\nHọc vấn: "+String.valueOf(m.get("cv_education"))+"\nKỹ năng: "+String.valueOf(m.get("cv_skills"))+"\nKinh nghiệm: "+String.valueOf(m.get("cv_experience"))+"\nMục tiêu: "+String.valueOf(m.get("cv_objective")));}}
